/* @lc app=leetcode id=1799 lang=kotlin */ class Solution { fun maxScore(nums: IntArray): Int = IntArray(1 shl nums.size).apply { (1 until (1 shl nums.size)).filter { it.countOneBits() % 2 == 0 }.forEach { mask -> nums.indices.forEach { j -> if ((mask and (1 shl j)) != 0) (j + 1 until nums.size).forEach { k -> if ((mask and (1 shl k)) != 0) this[mask] = maxOf(this[mask], this[mask xor (1 shl j) xor (1 shl k)] + java.math.BigInteger.valueOf(nums[j].toLong()).gcd(java.math.BigInteger.valueOf(nums[k].toLong())).toInt() * (mask.countOneBits() / 2)) } } } }[(1 shl nums.size) - 1] }